import ipaddress as ip

# 위에서부터 처음 맞는 규칙이 이긴다(first match)
rules = [
    {"id": 10, "src": "10.0.0.0/8",  "dst": "10.20.0.0/16", "port": "any", "action": "deny"},
    {"id": 20, "src": "10.1.0.0/16", "dst": "10.20.5.0/24", "port": 443,   "action": "accept"},
    {"id": 30, "src": "10.1.2.0/24", "dst": "10.30.0.0/16", "port": 22,    "action": "accept"},
]

def covers(a, b):
    return (ip.ip_network(b["src"]).subnet_of(ip.ip_network(a["src"]))
            and ip.ip_network(b["dst"]).subnet_of(ip.ip_network(a["dst"]))
            and (a["port"] == "any" or a["port"] == b["port"]))

for i, r in enumerate(rules):
    for upper in rules[:i]:
        if covers(upper, r):
            print(f"규칙 {r['id']}({r['action']})은 위 규칙 {upper['id']}({upper['action']})에 가려져 한 번도 안 걸린다")

# 출력:
# 규칙 20(accept)은 위 규칙 10(deny)에 가려져 한 번도 안 걸린다
